modules[S(590)] = function()
return function(import)
local HttpService = game:GetService(S(575))
local getPlaceId = import(S(178))
local log = import(S(487))
local ROOT_FOLDER = S(525)
local placeFolder = ROOT_FOLDER .. S(21) .. tostring(getPlaceId())
local filePath = placeFolder .. S(630)
local values = {}
local loaded = false
local function ensureFolders()
    if not (isfolder and makefolder) then
        return
    end
    if not isfolder(ROOT_FOLDER) then
        makefolder(ROOT_FOLDER)
    end
    if not isfolder(placeFolder) then
        makefolder(placeFolder)
    end
end
local function load()
    if loaded then
        return
    end
    loaded = true
    local ok, err = pcall(function()
        if isfile and isfile(filePath) then
            local decoded = HttpService:JSONDecode(readfile(filePath))
            if type(decoded) == S(440) then
                values = decoded
            end
        end
    end)
    if not ok then
        log(S(359) .. filePath .. S(751) .. tostring(err))
    end
end
local function save()
    local ok, err = pcall(function()
        ensureFolders()
        writefile(filePath, HttpService:JSONEncode(values))
    end)
    if not ok then
        log(S(113) .. filePath .. S(637) .. tostring(err))
    end
    return ok
end
local config = {}
function config.Get(key, default)
    load()
    local value = values[key]
    if value == nil then
        return default
    end
    return value
end
function config.Set(key, value)
    load()
    if values[key] == value then
        return
    end
    values[key] = value
    save()
end
function config.Path()
    return filePath
end
return config
end
end
