local LOG_FILE = S(399)
local function log(message)
    local line = os.date(S(567)) .. message
    print(line)
    local ok, err = pcall(function()
        if appendfile then
            if isfile and not isfile(LOG_FILE) then
                writefile(LOG_FILE, S(628))
            end
            appendfile(LOG_FILE, line .. S(272))
        elseif writefile then
            local existing = S(452)
