end
local function readPlacedPower(holder)
    for _, descendant in ipairs(holder:GetDescendants()) do
        if descendant:IsA(S(269)) then
            local digits = descendant.Text:match(S(505))
            if digits then
                return tonumber((digits:gsub(S(72), S(648))))
            end
        end
